class Solution {
  public int[] minBitwiseArray(List<Integer> nums) {
    int[] ans = new int[nums.size()];
    for (int i = 0; i < ans.length; i++) {
      int target = nums.get(i);
      ans[i] = -1;
      for (int a = 0; a < target; a++) {
        if ((a | (a + 1)) == target) {
          ans[i] = a;
          break;
        }
      }
    }
    return ans;
  }
}
